(33511, 'Acts 13:24', 'Acts', 13, 24, 'د عیسی د راتللو څخه مخکې یحیی د اسراییلو ټول قوم ته وعظ وکړ چې د خپلو ګناهونو څخه توبه وباسي او د تعمید غسل واخلي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_24.mp3', '', 1761754199, 1761754199),
(33512, 'Acts 13:25', 'Acts', 13, 25, 'کله چې یحیی خپله وظیفه سرته ورسوله، هغه وویل: ‹تاسو څه فکر کوئ چې زه څوک یم؟ زه هغه څوک نه یم چې تاسو یې انتظار کوئ. خو زما څخه وروسته هغه څوک راروان دی چې زه د هغه د څپلیو د تسمو د خلاصولو لیاقت هم نه لرم.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_25.mp3', '', 1761754199, 1761754199),
(33513, 'Acts 13:26', 'Acts', 13, 26, 'ای ورونو! ای د ابراهیم اولادې، او ای غیریهودیانو چې له خدایه وېرېږئ! مونږ هغه خلک یو چې د خلاصون دا پیغام راته رالېږل شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_26.mp3', '', 1761754199, 1761754199),
(33514, 'Acts 13:27', 'Acts', 13, 27, 'د اورشلیم خلکو او د هغوی مشرانو نه عیسی وپېژانده او نه هغوی د پیغمبرانو په پیغام باندې پوه شول چې د هر سبت په ورځ لوستل کیږي. خو هغوی د عیسی په محکومولو سره د پیغمبرانو پېشګویانې پوره کړلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_27.mp3', '', 1761754199, 1761754199),
(33515, 'Acts 13:28', 'Acts', 13, 28, 'سره له دې چې کوم داسې جرم یې پیدا نه کړ چې هغه ته دې د مرګ سزا ورکړل شي، خو د پیلاتوس څخه یې وغوښتل چې هغه اعدام کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_28.mp3', '', 1761754199, 1761754199),
(33516, 'Acts 13:29', 'Acts', 13, 29, 'کله چې هغوی هغه ټول شیان چې د هغه په هکله لیکل شوي وو سرته ورسول، نو هغه یې د صلیب څخه راښکته کړ او په قبر کې یې کېښود.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_29.mp3', '', 1761754199, 1761754199),
(33517, 'Acts 13:30', 'Acts', 13, 30, 'خو خدای هغه بېرته راژوندی کړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_30.mp3', '', 1761754199, 1761754199),
(33518, 'Acts 13:31', 'Acts', 13, 31, 'او کوم خلک چې د هغه سره د جلیل څخه اورشلیم ته راغلي وو، تر ډېرو ورځو پورې هغوی ته ورښکاره شو او هغوی اوس د اسراییلو د خلکو په مخکې د هغه شاهدان دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_31.mp3', '', 1761754199, 1761754199),
(33519, 'Acts 13:32', 'Acts', 13, 32, 'اوس مونږ تاسو ته هغه زېری اوروو چې خدای زمونږ د نیکونو سره وعده کړې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_32.mp3', '', 1761754199, 1761754199),
(33520, 'Acts 13:33', 'Acts', 13, 33, 'خدای دا وعده زمونږ دپاره چې د هغوی اولاده یو، د مړو نه د عیسی په بیا راژوندي کولو سره پوره کړه. لکه څنګه چې په دوهم زبور کې لیکل شوي دي: ته مې زوی، زه دې نن پلار شوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_33.mp3', '', 1761754199, 1761754199),
(33521, 'Acts 13:34', 'Acts', 13, 34, 'خدای هغه د مړو څخه راژوندی کړ او دې ته یې پرېنښود چې مړی یې په قبر کې خراب شي. او په دې هکله خدای داسې وویل: زه به تاته هغه ځانګړي او یقیني برکتونه درکړم چې د داود سره مې وعده کړې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_34.mp3', '', 1761754199, 1761754199),
(33522, 'Acts 13:35', 'Acts', 13, 35, 'او د زبور په بل ځای کې داود وایي: ته به پرېنږدې مړی د خپل سپېڅلي خادم چې شي خراب', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_35.mp3', '', 1761754199, 1761754199),
(33523, 'Acts 13:36', 'Acts', 13, 36, 'ځکه چې داود په خپله زمانه کې د خدای اراده پوره کړه او بیا مړ شو او د خپلو نیکونو سره ښخ کړای شو او مړی یې په قبر کې خراب شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_36.mp3', '', 1761754199, 1761754199),
(33524, 'Acts 13:37', 'Acts', 13, 37, 'خو کوم کس چې خدای د مړو څخه راژوندی کړ، د هغه مړی خراب نه شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_37.mp3', '', 1761754199, 1761754199),
(33525, 'Acts 13:38', 'Acts', 13, 38, '‏-۳۹ نو ای زما ورونو! تاسو باید په دې پوه شئ چې د ګناهونو د بخښنې پیغام د عیسی په وسیله تاسو ته اعلانیږي او هرڅوک چې په هغه باندې ایمان راوړي، هغه به د هغو ټولو ګناهونو څخه خلاص شي چې د موسی شریعت ونه شو کولای هغه ته خلاصون ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_38.mp3', '', 1761754199, 1761754199),
(33526, 'Acts 13:40', 'Acts', 13, 40, 'نو پام کوئ چې پیغمبرانو چې څه ویلي دي هغه په تاسو عملي نه شي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_40.mp3', '', 1761754199, 1761754199),
(33527, 'Acts 13:41', 'Acts', 13, 41, 'ګورئ ای ملنډو وهونکو! حیران او تباه شئ، ځکه چې زه به ستاسو په ژوندانه کې یو داسې کار وکړم، که څوک یې تاسو ته بیان هم کړي، نو باور به ورباندې ونه کړئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_41.mp3', '', 1761754199, 1761754199),
(33528, 'Acts 13:42', 'Acts', 13, 42, 'کله چې پولوس او برناباس د کنیسې څخه وتل، نو خلکو ورڅخه وغوښتل چې د راتلونکي سبت په ورځ بیا راشي او د دې شیانو په هکله دوی ته خبرې وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_42.mp3', '', 1761754199, 1761754199),
(33529, 'Acts 13:43', 'Acts', 13, 43, 'کله چې غونډه پای ته ورسېدله، نو ډېر یهودیان او هغه دینداره خلک چې یهودیان شوي وو، د پولوس او برناباس سره روان شول. پولوس او برناباس د هغوی سره خبرې وکړې او هغوی یې وهڅول چې تل د خدای په فضل باندې توکل ولري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_43.mp3', '', 1761754199, 1761754199),
(33530, 'Acts 13:44', 'Acts', 13, 44, 'د راتلونکي سبت په ورځ د ښار نژدې ټول اوسېدونکي راغلل چې د څښتن عیسی پیغام واوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_44.mp3', '', 1761754199, 1761754199),
(33531, 'Acts 13:45', 'Acts', 13, 45, 'کله چې ځینو یهودیانو دا ګڼه‌ګوڼه ولیدله، نو بخیلي ورسره پیدا شوه. هغوی د پولوس د خبرو سره مخالفت پیل کړ او هغه ته یې سپکاوی وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_45.mp3', '', 1761754199, 1761754199),
(33532, 'Acts 13:46', 'Acts', 13, 46, 'خو پولوس او برناباس په زړورتیا سره خبرې کولې او ویل یې: «دا ضروري وه چې د خدای پیغام لومړی تاسو ته واورول شي. خو څرنګه چې تاسو هغه ونه مانه او خپل ځانونه مو د تلپاتې ژوندون وړ ونه ګڼل، نو مونږ به اوس تاسو پرېږدو او غیریهودیانو ته به ورشو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_46.mp3', '', 1761754199, 1761754199),
(33533, 'Acts 13:47', 'Acts', 13, 47, 'نو ځکه څښتن مونږ ته داسې حکم وکړ: زه به ستا څخه د غیریهودیانو دپاره رڼا جوړه کړم، ترڅو ته ټولې نړۍ ته د خلاصون وسیله وګرځې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_47.mp3', '', 1761754199, 1761754199),
(33534, 'Acts 13:48', 'Acts', 13, 48, 'کله چې غیریهودیانو دا خبرې واورېدلې، نو ډېر خوشحاله شول او د څښتن عیسی د پیغام ستاینه یې وکړه او کوم خلک چې د تلپاتې ژوندون دپاره غوره کړای شوي وو، هغوی ایمان راوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_48.mp3', '', 1761754199, 1761754199),
(33535, 'Acts 13:49', 'Acts', 13, 49, 'د څښتن پیغام په هغه ټوله سیمه کې خپور شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_49.mp3', '', 1761754199, 1761754199),
(33536, 'Acts 13:50', 'Acts', 13, 50, 'خو یهودیانو دینداره او عزتمندې ښځې او د ښار مشران د پولوس او برناباس په خلاف داسې ولمسول چې د هغوی په ځورولو یې پیل وکړ او د خپلې سیمې څخه یې وشړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_50.mp3', '', 1761754199, 1761754199),
(33537, 'Acts 13:51', 'Acts', 13, 51, 'نو پولوس او برناباس د خپلو پښو خاورې د هغه ښار د خلکو په وړاندې د نښې په توګه وڅنډلې او د قونیې ښار ته لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_51.mp3', '', 1761754199, 1761754199),
(33538, 'Acts 13:52', 'Acts', 13, 52, 'خو د هغه ځای ایمانداران د خوشحالۍ او روح القدس څخه ډک شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_52.mp3', '', 1761754199, 1761754199),
(33539, 'Mark 5:1', 'Mark', 5, 1, 'عیسی او شاګردان یې د بحیرې بلې غاړې ته د جدریان سیمې ته لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_1.mp3', '', 1761754199, 1761754199),
(33540, 'Mark 5:2', 'Mark', 5, 2, 'کله چې عیسی د کشتۍ څخه راښکته شو، نو هلته د یو پېریاني سړي سره چې د هدیرې څخه راوتلی ؤ، مخامخ شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_2.mp3', '', 1761754199, 1761754199),
(33541, 'Mark 5:3', 'Mark', 5, 3, 'هغه په هدیره کې اوسېده او هېچا نه شو کولای چې حتی هغه په زنځیرونو وتړي او را‌ایسار یې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_3.mp3', '', 1761754199, 1761754199),
(33542, 'Mark 5:4', 'Mark', 5, 4, 'ځکه چې څو څو ځلې یې د هغه په پښو او لاسونو کې ځولنې او زنځیرونه اچولي وو، خو هرځل یې زنځیرونه شکولي او ځولنې یې ماتې کړې وې او داسې قوي سړی نه ؤ چې هغه یې ارام کړی وای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_4.mp3', '', 1761754199, 1761754199),
(33543, 'Mark 5:5', 'Mark', 5, 5, 'هغه به شپه او ورځ په قبرونو او غرونو کې ګرځېده او تل به یې چیغې وهلې او خپل ځان به یې په تیږو زخمي کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_5.mp3', '', 1761754199, 1761754199),
(33544, 'Mark 5:6', 'Mark', 5, 6, 'کله چې هغه عیسی د لېرې څخه ولیده، نو منډه یې کړه او د هغه په پښو کې پرېوت', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_6.mp3', '', 1761754199, 1761754199),
(33545, 'Mark 5:7', 'Mark', 5, 7, 'او په لوړ اواز یې چیغې ووهلې: «ای عیسی، ای د خدای تعالی زویه! زما سره څه کار لرې؟ د خدای په خاطر ما مه په عذابوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_7.mp3', '', 1761754199, 1761754199),
(33546, 'Mark 5:8', 'Mark', 5, 8, 'دا ځکه چې عیسی هغه ته ویلي وو: «ای پېریه، د دې سړي څخه راووځه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_8.mp3', '', 1761754199, 1761754199),
(33547, 'Mark 5:9', 'Mark', 5, 9, 'بیا عیسی د هغه څخه پوښتنه وکړه: «ستا نوم څه دی؟» هغه ځواب ورکړ: «زما نوم لښکر دی، ځکه چې زمونږ شمېر زیات دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_9.mp3', '', 1761754199, 1761754199),
(33548, 'Mark 5:10', 'Mark', 5, 10, 'هغه بیا عیسی ته ډېره زاري وکړه چې هغوی د هغې سیمې څخه ونه شړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_10.mp3', '', 1761754199, 1761754199),
(33549, 'Mark 5:11', 'Mark', 5, 11, 'په دې وخت کې هلته د غونډۍ په لمنه کې د خوګانو یوه لویه رمه څرېدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_11.mp3', '', 1761754199, 1761754199),
(33550, 'Mark 5:12', 'Mark', 5, 12, 'نو پېریانو عیسی ته زاري وکړه: «مونږ خوګانو ته ولېږه او اجازه راکړه چې په هغوی کې ورننوځو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_12.mp3', '', 1761754199, 1761754199),
(33551, 'Mark 5:13', 'Mark', 5, 13, 'عیسی هغوی ته اجازه ورکړه او پېریان د هغه سړي څخه ووتل او په خوګانو کې ورننوتل. ټوله رمه چې شاوخوا دوه زره خوګان وو، په منډه له کمره څخه ښکته بحیرې ته ولوېدله او ډوبه شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_13.mp3', '', 1761754199, 1761754199),
(33552, 'Mark 5:14', 'Mark', 5, 14, 'د خوګانو ساتونکي وتښتېدل او دا خبر یې د ښار او شاوخوا کلیوالي سیمو خلکو ته ورساوه. خلک د ښار څخه ووتل ترڅو څه چې پېښ شوي وو، وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_14.mp3', '', 1761754199, 1761754199),
(33553, 'Mark 5:15', 'Mark', 5, 15, 'کله چې هغوی عیسی ته راغلل او هغه لېونی چې ډېر پېریان په کې وو، ولیده چې کالي یې اغوستي وو او ذهن یې بېرته ښه شوی ؤ او هلته ناست ؤ، نو هغوی ووېرېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_15.mp3', '', 1761754199, 1761754199),
(33554, 'Mark 5:16', 'Mark', 5, 16, 'کومو خلکو چې دا پېښه لیدلې وه او د هغه پېریانو نیولي سړي او خوګانو سره چې څه شوي وو هغه یې نورو خلکو ته وویل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_16.mp3', '', 1761754199, 1761754199),
(33555, 'Mark 5:17', 'Mark', 5, 17, 'بیا هغو خلکو عیسی ته زارۍ وکړلې چې د دوی د سیمې څخه لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_17.mp3', '', 1761754199, 1761754199),
(33556, 'Mark 5:18', 'Mark', 5, 18, 'کله چې عیسی کشتۍ ته ورختلو نو هغه سړي چې مخکې پېریانو نیولی ؤ، عیسی ته زاري وکړه چې اجازه ورته ورکړي چې ورسره لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_18.mp3', '', 1761754199, 1761754199),
(33557, 'Mark 5:19', 'Mark', 5, 19, 'خو عیسی هغه ته اجازه ورنه کړه او ورته ویې ویل: «بېرته خپل کور او خپلې کورنۍ ته ورشه او هغوی ته ووایه چې څښتن ستا دپاره څومره لوی کار وکړ او څنګه یې په تا باندې رحم وکړ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_19.mp3', '', 1761754199, 1761754199),
(33558, 'Mark 5:20', 'Mark', 5, 20, 'نو هغه سړی لاړ او څه چې عیسی د هغه دپاره کړي وو د هغو په هکله یې د دکاپولس په سیمه کې ټول خلک خبر کړل او هغوی ټول حیران شول. یوې ښځې ته شفا ورکول او د مړې انجلۍ راژوندي کول (متي ۹‏:‌۱۸‌‏-‌۲۶ او لوقا ۸‏:‌۴۰‌‏-‌۵۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_20.mp3', '', 1761754199, 1761754199),
(33559, 'Mark 5:21', 'Mark', 5, 21, 'کله چې عیسی یوځل بیا په کشتۍ کې د بحیرې بلې غاړې ته پورې وت، نو هلته د بحیرې په غاړه ګڼ شمېر خلک ورڅخه راتاو شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_21.mp3', '', 1761754199, 1761754199),
(33560, 'Mark 5:22', 'Mark', 5, 22, 'بیا د کنیسې یو مشر چې یایروس نومېده راغی او کله چې هغه عیسی ولیده نو په پښو کې یې پرېوت،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark5_verse_22.mp3', '', 1761754199, 1761754199),
